const failures=[];const newRows=[];const now=$now.setZone('America/Sao_Paulo').toFormat('yyyy-MM-dd HH:mm:ss');
const T=v=>"'"+t(v);
for(const k of req.ids){
 const list=byId.get(k)||[];
 if(knownIds.has(k)){failures.push(`${k}: já cadastrada`);continue}
 if(!list.length){failures.push(`${k}: não localizada no faturamento`);continue}
 if(list.length>1){failures.push(`${k}: localizada em mais de uma filial, use a chave`);continue}
 const d=list[0];if(knownKeys.has(num(d.CHAVE_NFE))){failures.push(`${k}: chave já cadastrada`);continue}
 newRows.push({IDENTIFICACAO:T(k),NOTA_FISCAL:T(num(d.NF_SAIDA).padStart(9,'0')),CARRO:T(req.carro),
 MARCA:t(d.MARCA),REFERENCIA:T(d.REFERENCIA),DESCRICAO_MATERIAL:T(d.DESCRICAO_MATERIAL),CANAL:t(d.CANAL),
 QUANTIDADE:Number(d.QUANTIDADE??0),VALOR:Number(d.VALOR??0),STATUS_INTEGRACAO:'INTEGRADO',
 DATA_AGENDAMENTO:t(d.DATA_AGENDAMENTO),INICIO_CONFERENCIA_SUL:t(d.INICIO_CONFERENCIA_SUL),FIM_CONFERENCIA_SUL:t(d.FIM_CONFERENCIA_SUL),
 DATA_EMBARQUE:t(d.DATA_EMBARQUE),PREVISAO_CHEGADA:t(d.PREVISAO_CHEGADA),RECEBIMENTO_RIO:'Não',
 DATA_ENTRADA_FISCAL:t(d.DATA_ENTRADA_FISCAL),ROMANEIO:t(d.ROMANEIO)?T(d.ROMANEIO):'',PLACA:t(d.PLACA)?T(d.PLACA):'',
