 TRANSPORTADORA:t(d.TRANSPORTADORA)?T(d.TRANSPORTADORA):'',MENSAGEM:'',ULTIMA_ATUALIZACAO:now});
}
// Não gravar lote parcialmente: evita registros inesperados no fechamento operacional.
if(failures.length)return [{json:{ok:false,erro:'Lote recusado. Nenhuma NF foi cadastrada.',detalhes:failures}}];
return newRows.map(r=>({json:{ok:true,...r}}));

let b=$input.first().json.body??{};if(typeof b==='string'){try{b=JSON.parse(b)}catch(e){b={}}}
const car=String(b.carro??'').trim();const serie=String(b.serie??'').trim();const nfs=Array.isArray(b.nfs)?b.nfs.map(v=>String(v).trim()):[];
