if(!car||car.length>60)erro='Informe o carro (até 60 caracteres).';
else if(!/^\d{1,3}$/.test(serie))erro='Série inválida.';
else if(!nfs.length||nfs.length>100)erro='Informe de 1 a 100 NFs.';
