 if(/^sim$/i.test(t(row.RECEBIMENTO_RIO)))return fail('Esta NF já foi recebida. Não é permitido desfazer o recebimento.');
 upd.RECEBIMENTO_RIO='Sim';upd.DATA_RECEBIMENTO_RIO=now;
}
